INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine 1:1-Beziehung in Datenbanken immer zwingend ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Beziehungen hängen vom Modell ab"}, {"text": "Ja", "correct": false, "because": "Nicht immer erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Beziehungen zwischen Tabellen definiere?', 3, '[{"text": "Logische Konsistenz", "correct": true, "because": "Sichert Datenintegrität"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Sekundär"}, {"text": "Bunte Diagramme", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kardinalitäten sind in einer Datenbank typisch?', 5, '[{"text": "1:1", "correct": true, "because": "Einzigartige Zuordnung"}, {"text": "1:n", "correct": true, "because": "Einer zu vielen"}, {"text": "1:0", "correct": false, "because": "Kein Standard"}, {"text": "n:m ohne Tabelle", "correct": false, "because": "Benötigt Zwischentabelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine n:m-Beziehung braucht eine Zwischentabelle. b) Eine 1:n-Beziehung ist immer bidirektional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "1:n ist meist unidirektional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Datenbankbeziehung entwerfe?', 4, '[{"text": "Fremdschlüssel", "correct": false, "because": "Sichert Referenz"}, {"text": "Geschäftslogik", "correct": false, "because": "Definiert Beziehung"}, {"text": "Farbschema", "correct": true, "because": "Irrelevant für Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine 1:n-Beziehung immer einen Fremdschlüssel braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Verknüpft Tabellen"}, {"text": "Nein", "correct": false, "because": "Fremdschlüssel ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Modell wähle ich für eine Beziehung, bei der ein Kunde viele Bestellungen hat?', 3, '[{"text": "1:n", "correct": true, "because": "Ein Kunde, viele Bestellungen"}, {"text": "1:1", "correct": false, "because": "Zu restriktiv"}, {"text": "n:m", "correct": false, "because": "Zu komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente definieren eine n:m-Beziehung korrekt?', 5, '[{"text": "Zwischentabelle", "correct": true, "because": "Verknüpft Entitäten"}, {"text": "Fremdschlüssel", "correct": true, "because": "Referenziert Tabellen"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}, {"text": "Schnelle CPU", "correct": false, "because": "Kein Datenbankfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine 1:1-Beziehung spart Speicherplatz. b) Sie ist immer zwingend. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine 1:n-Beziehung?', 4, '[{"text": "Fremdschlüssel", "correct": false, "because": "Verknüpft Tabellen"}, {"text": "Primärschlüssel", "correct": false, "because": "Identifiziert Datensätze"}, {"text": "Bunte Diagramme", "correct": true, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine n:m-Beziehung ohne Zwischentabelle möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Zwischentabelle ist Pflicht"}, {"text": "Ja", "correct": false, "because": "Nicht standardkonform"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine 1:1-Beziehung?', 4, '[{"text": "Klare Zuordnung", "correct": true, "because": "Vermeidet Mehrdeutigkeit"}, {"text": "Datenintegrität", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Schnellere Abfragen", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine 1:n-Beziehung immer komplexer als 1:1 ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexität hängt vom Modell ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Datenbank mit vielen Beziehungen entwerfe?', 3, '[{"text": "Konsistenz", "correct": true, "because": "Vermeidet Datenfehler"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Qualität zählt"}, {"text": "Bunte Visuals", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kardinalität definiert Beziehungsarten. b) Sie beeinflusst die Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware unabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei einer n:m-Beziehung?', 5, '[{"text": "Zwischentabelle", "correct": true, "because": "Verknüpft Entitäten"}, {"text": "Fremdschlüssel", "correct": true, "because": "Sichert Referenzen"}, {"text": "Schnelle CPU", "correct": false, "because": "Kein Modellfaktor"}, {"text": "Bildschirmgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine 1:1-Beziehung entwerfe?', 3, '[{"text": "Eindeutigkeit", "correct": false, "because": "Sicherer Zuordnung"}, {"text": "Integrität", "correct": false, "because": "Vermeidet Fehler"}, {"text": "Tabellenfarbe", "correct": true, "because": "Kein funktionaler Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Tabelle mehrere 1:n-Beziehungen haben?', 3, '[{"text": "Ja", "correct": true, "because": "Mehrere Fremdschlüssel möglich"}, {"text": "Nein", "correct": false, "because": "Technisch machbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kardinalität die Abfragegeschwindigkeit beeinflusst?', 2, '[{"text": "Ja", "correct": true, "because": "Beziehungen wirken auf Joins"}, {"text": "Nein", "correct": false, "because": "Indirekter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich eine Beziehung für Kunden und Projekte entwerfe?', 4, '[{"text": "Geschäftslogik", "correct": true, "because": "Definiert Kardinalität"}, {"text": "Schnelle Hardware", "correct": false, "because": "Nicht relevant"}, {"text": "Bunte Diagramme", "correct": false, "because": "Nur visualisierung"}]');
